import React, { useEffect, useState, useRef } from "react";
import { School, Bell } from "lucide-react";
import { useNavigate } from "react-router-dom";

import { useAuth } from "../context/AuthContext.jsx";
import axios from "axios";

function HomeHeader({ compact = false }) {
  const navigate = useNavigate();
  const { currentUser } = useAuth();
  const [unreadCount, setUnreadCount] = useState(0);
  const [notifications, setNotifications] = useState([]);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [highlight, setHighlight] = useState(false);
  const containerRef = useRef(null);
  const dropdownRef = useRef(null);
  const prevUnreadRef = useRef(0);

  const displayName = currentUser?.name || currentUser?.email?.split("@")[0] || "";

  const handleLogoClick = () => {
    navigate("/");
  };

  const handlePrimaryClick = () => {
    if (currentUser) {
      navigate("/dashboard");
      return;
    }

    navigate("/login");
  };

  const handleRegisterClick = () => {
    navigate('/register');
  };

  useEffect(() => {
    let mounted = true;

    const fetchUnread = async () => {
      try {
        if (!currentUser?.token) return;
        const resp = await axios.get("http://localhost:8081/api/notifications/unread-count", {
          headers: { Authorization: `Bearer ${currentUser.token}` },
        });
        if (!mounted) return;
        const newCount = resp.data?.unreadCount || 0;
        // highlight when new notifications arrive
        if (newCount > (prevUnreadRef.current || 0)) {
          setHighlight(true);
          setTimeout(() => setHighlight(false), 6000);
        }
        prevUnreadRef.current = newCount;
        setUnreadCount(newCount);
      } catch (err) {
        // ignore
      }
    };

    fetchUnread();
    const id = setInterval(fetchUnread, 30000);
    return () => {
      mounted = false;
      clearInterval(id);
    };
  }, [currentUser]);

  useEffect(() => {
    const onDocClick = (e) => {
      if (!dropdownOpen) return;
      const clickedInsideBell = containerRef.current && containerRef.current.contains(e.target);
      const clickedInsideDropdown = dropdownRef.current && dropdownRef.current.contains(e.target);
      if (!clickedInsideBell && !clickedInsideDropdown) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener('click', onDocClick);
    return () => document.removeEventListener('click', onDocClick);
  }, [dropdownOpen]);

  const fetchNotifications = async () => {
    if (!currentUser?.token) return;
    try {
      const resp = await axios.get("http://localhost:8081/api/notifications", {
        headers: { Authorization: `Bearer ${currentUser.token}` },
      });
      setNotifications(resp.data || []);
    } catch (err) {
      // ignore
    }
  };

  const handleBellClick = async () => {
    setDropdownOpen(open => {
      const next = !open;
      if (!open) {
        // opening
        fetchNotifications();
        // clear transient highlight when user opens
        setHighlight(false);
      }
      return next;
    });
  };

  const handleNotifClick = async (notif) => {
    if (!currentUser?.token) return;
    try {
      if (!notif.read) {
        await axios.patch(`http://localhost:8081/api/notifications/${notif.id}/read`, {}, {
          headers: { Authorization: `Bearer ${currentUser.token}` }
        });
        setNotifications(ns => ns.map(n => n.id === notif.id ? { ...n, read: true } : n));
        setUnreadCount(c => Math.max(0, c - 1));
      }
    } catch (err) {
      // ignore
    }
    // navigate to full notifications page for details
    setDropdownOpen(false);
    navigate('/notifications');
  };

  const handleMarkAll = async () => {
    if (!currentUser?.token) return;
    try {
      await axios.patch('http://localhost:8081/api/notifications/read-all', {}, {
        headers: { Authorization: `Bearer ${currentUser.token}` }
      });
      setNotifications(ns => ns.map(n => ({ ...n, read: true })));
      setUnreadCount(0);
    } catch (err) {
      // ignore
    }
  };

  const formatNotifType = (t) => {
    if (!t) return '';
    return t.replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
  };

  return (
    <nav style={compact ? styles.compactNav : styles.nav}>
      <button type="button" onClick={handleLogoClick} style={styles.logoBtn}>
        <School size={28} color="#a78bfa" />
        <span style={styles.logoText}>Smart Campus</span>
      </button>

      <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <div ref={containerRef} style={{ position: 'relative', display: 'inline-block' }}>
          <button
            type="button"
            onClick={handleBellClick}
            style={{ ...styles.notifyBtn, ...(highlight ? styles.notifyBtnHighlight : {}) }}
            aria-label="Notifications"
          >
            <Bell size={20} color="#fff" />
            {unreadCount > 0 && <span style={styles.notifyBadge}>{unreadCount}</span>}
          </button>

          {dropdownOpen && (
            <div style={styles.overlay} onClick={() => setDropdownOpen(false)}>
              <div ref={dropdownRef} style={styles.modalPanel} onClick={(e) => e.stopPropagation()}>
                <div style={styles.modalHeader}>
                  <strong>Notifications</strong>
                  <button onClick={handleMarkAll} style={styles.markAllBtn}>Mark all as read</button>
                </div>

                <div style={styles.modalList}>
                  {notifications.length === 0 ? (
                    <div style={styles.noNotifications}>No notifications</div>
                  ) : (
                    notifications.map(n => (
                      <div key={n.id} onClick={() => handleNotifClick(n)} style={{ ...styles.notifItem, ...(n.read ? {} : styles.notifUnread) }}>
                        <div style={styles.notifType}>{formatNotifType(n.type)}</div>
                        <div style={styles.notifMessage}>{n.message}</div>
                        <div style={styles.notifTime}>{new Date(n.createdAt).toLocaleString()}</div>
                      </div>
                    ))
                  )}
                </div>

                <div style={styles.modalFooter}>
                  <button onClick={() => setDropdownOpen(false)} style={styles.closeBtn}>Close</button>
                </div>
              </div>
            </div>
          )}
        </div>

        {currentUser ? (
          <button type="button" onClick={handlePrimaryClick} style={styles.userBtn}>{displayName}</button>
        ) : (
          <>
            <button type="button" onClick={handlePrimaryClick} style={styles.signInBtn}>Sign In</button>
            <button type="button" onClick={handleRegisterClick} style={styles.registerBtn}>Register</button>
          </>
        )}
      </div>
    </nav>
  );
}

const styles = {
  nav: {
    padding: "20px 50px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "rgba(255, 255, 255, 0.03)",
    backdropFilter: "blur(10px)",
    position: "sticky",
    top: 0,
    zIndex: 100,
    borderBottom: "1px solid rgba(255, 255, 255, 0.05)"
  },
  compactNav: {
    padding: "16px 28px",
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "linear-gradient(90deg, rgba(11,31,58,0.98), rgba(30,58,138,0.96))",
    backdropFilter: "blur(14px)",
    borderBottom: "1px solid rgba(255, 255, 255, 0.08)",
    position: "sticky",
    top: 0,
    zIndex: 100
  },
  logoBtn: {
    display: "flex",
    alignItems: "center",
    gap: "10px",
    border: "none",
    background: "transparent",
    padding: 0,
    cursor: "pointer"
  },
  logoText: { fontSize: "20px", fontWeight: 700, letterSpacing: "-0.5px", color: "#fff" },
  signInBtn: {
    padding: "8px 22px",
    borderRadius: "10px",
    border: "none",
    background: "linear-gradient(135deg, #667eea, #764ba2)",
    color: "#fff",
    fontSize: "14px",
    fontWeight: 600,
    cursor: "pointer",
    boxShadow: "0 4px 15px rgba(118, 75, 162, 0.3)",
    transition: "all 0.3s ease"
  },
  userBtn: {
    padding: "8px 18px",
    borderRadius: "999px",
    border: "1px solid rgba(167, 139, 250, 0.35)",
    background: "rgba(167, 139, 250, 0.12)",
    color: "#f5f3ff",
    fontSize: "14px",
    fontWeight: 700,
    cursor: "pointer",
    letterSpacing: "-0.2px"
  },
  notifyBtn: {
    position: 'relative',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 40,
    height: 40,
    borderRadius: 10,
    background: 'rgba(255,255,255,0.03)',
    border: '1px solid rgba(255,255,255,0.04)',
    cursor: 'pointer'
  ,
  notifyBtnHighlight: {
    boxShadow: '0 6px 20px rgba(239,68,68,0.28)',
    transform: 'scale(1.04)'
  },
  dropdown: {
    position: 'fixed',
    top: 80,
    right: 24,
    width: 320,
    maxHeight: '50vh',
    overflow: 'auto',
    background: 'rgba(15,12,41,0.98)',
    color: '#fff',
    borderRadius: 10,
    boxShadow: '0 10px 30px rgba(0,0,0,0.35)',
    padding: 8,
    zIndex: 1400
  },
  overlay: {
    position: 'fixed',
    inset: 0,
    background: 'rgba(0,0,0,0.35)',
    zIndex: 1400,
    display: 'flex',
    justifyContent: 'flex-end',
    alignItems: 'flex-start',
    paddingTop: 80,
    paddingRight: 24
  },
  modalPanel: {
    width: 360,
    maxHeight: '70vh',
    overflow: 'auto',
    background: 'linear-gradient(180deg, rgba(18,17,38,0.98), rgba(12,10,30,0.98))',
    color: '#fff',
    borderRadius: 10,
    boxShadow: '0 15px 40px rgba(0,0,0,0.5)',
    padding: 12
  },
  modalHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 8
  },
  modalList: {
    display: 'flex',
    flexDirection: 'column',
    gap: 10
  },
  modalFooter: {
    display: 'flex',
    justifyContent: 'flex-end',
    marginTop: 10
  },
  closeBtn: {
    padding: '8px 14px',
    borderRadius: 8,
    background: 'rgba(255,255,255,0.04)',
    color: '#fff',
    border: 'none',
    cursor: 'pointer'
  },
  dropdownHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '6px 8px',
    borderBottom: '1px solid rgba(255,255,255,0.04)'
  },
  markAllBtn: {
    background: 'transparent',
    border: 'none',
    color: '#9fb3ff',
    cursor: 'pointer',
    fontSize: 12
  },
  dropdownList: {
    display: 'flex',
    flexDirection: 'column',
    gap: 8,
    padding: 8
  },
  noNotifications: {
    padding: 12,
    color: '#cbd5e1'
  },
  notifItem: {
    padding: 10,
    borderRadius: 8,
    background: 'rgba(255,255,255,0.02)',
    cursor: 'pointer'
  },
  notifUnread: {
    background: 'rgba(99,102,241,0.12)'
  },
  notifType: { fontSize: 12, fontWeight: 700, color: '#a0b9ff' },
  notifMessage: { fontSize: 13, marginTop: 6 },
  notifTime: { fontSize: 11, color: '#9aa7d6', marginTop: 6 }
  },
  registerBtn: {
    padding: "8px 18px",
    borderRadius: "10px",
    border: "1px solid rgba(167,139,250,0.18)",
    background: "transparent",
    color: "#cbd5ff",
    fontSize: "14px",
    fontWeight: 600,
    cursor: "pointer"
  },
  notifyBadge: {
    position: 'absolute',
    top: -6,
    right: -6,
    background: '#ef4444',
    color: '#fff',
    fontSize: 11,
    fontWeight: 700,
    padding: '2px 6px',
    borderRadius: 20
  }
};

export default HomeHeader;